<section class="form-panel" data-livestock-space="transfers"><h3 class="livestock-section-title"><span class="livestock-heading-icon"><i class="bi bi-truck" aria-hidden="true"></i></span><span>BTR vers la boucherie</span></h3><?php if(Auth::can('livestock','create')): ?><button type="button" class="btn-secondary" data-workspace-modal-open="livestock-transfers"><i class="bi bi-truck" aria-hidden="true"></i> Transférer vers la boucherie</button><?php endif; ?><table class="enterprise-table"><thead><tr><th>Référence</th><th>Lot</th><th>Quantité</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($transfers as$t):?><tr><td><?=e($t['document_number']?:$t['transfer_number'])?></td><td><?=e($t['batch_number'])?></td><td><?=e($t['source_unit']==='head'?$t['quantity_heads'].' têtes':$t['quantity_kg'].' kg')?></td><td><?=e($statusLabels[$t['status']]??$t['status'])?></td><td><?php if($t['status']==='draft' && Auth::can('livestock','validate')):?><form data-confirm="Confirmer cette action sur le lot ? Les stocks concernés seront mis à jour." method="post" action="<?=e(base_url('livestock/transfers/'.$t['id'].'/approve'))?>"><?=csrf_field()?><span class="livestock-record-site">Site : <?php $recordSiteName='';foreach(Auth::sites() as $recordSite)if((int)$recordSite['id']===(int)$t['source_site_id'])$recordSiteName=$recordSite['name'];echo e($recordSiteName); ?> (lié au document)</span><button class="btn-secondary"><i class="bi bi-check2-circle" aria-hidden="true"></i><span>Approuver</span></button></form><?php elseif($t['status']==='approved' && Auth::can('livestock','update')):?><form data-confirm="Confirmer cette action sur le lot ? Les stocks concernés seront mis à jour." method="post" action="<?=e(base_url('livestock/transfers/'.$t['id'].'/dispatch'))?>"><?=csrf_field()?><span class="livestock-record-site">Site : <?php $recordSiteName='';foreach(Auth::sites() as $recordSite)if((int)$recordSite['id']===(int)$t['source_site_id'])$recordSiteName=$recordSite['name'];echo e($recordSiteName); ?> (lié au document)</span><button class="btn-secondary"><i class="bi bi-truck" aria-hidden="true"></i><span>Expédier</span></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>

